class Solution {
  public int hIndex(int[] citations) {
    int n = citations.length, lo = 0, hi = n;
    // first index i with citations[i] >= n - i
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (citations[mid] >= n - mid) hi = mid;
      else lo = mid + 1;
    }
    return n - lo;
  }
}
